package ThermalControl {
    doc /* Thermal control subsystem model (sample) */
    private import ScalarValues::*;
    private import ISQ::*;
    private import SI::*;
    public import Interfaces::*;
    public import Requirements::*;
    attribute def TemperatureValue :> ThermodynamicTemperatureValue;

    enum def HeaterMode { enum off; enum low; enum high; }

    // Structure

    part def ThermalController {
        doc /* Closed-loop regulator for panel temperature */
        attribute setpoint : TemperatureValue;
        attribute tolerance : Real = 0.5;
        port cmdIn : CommandPort;
        port heaterOut : PowerPort;
        port sensorIn : ~TempPort;
        perform action regulate : RegulateTemperature;
    }

    part def Heater {
        doc /* Resistive film heater */
        attribute maxPower : PowerValue;
        attribute state : HeaterState;
        port pwrIn : ~PowerPort;
    }

    part def TempSensor {
        doc /* Platinum RTD temperature sensor */
        attribute accuracy : Real;
        attribute sampleRate : FrequencyValue;
        port tempOut : TempPort;
    }
